import axios from 'axios';

// On utilise l'adresse IP pour éviter les blocages CORS du navigateur
const API_BASE_URL = 'http://192.168.1.214:8001';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: { 
    'Content-Type': 'application/json' 
  },
});

/**
 * INTERCEPTEUR DE REQUÊTE
 * Injecte automatiquement le token JWT dans chaque appel API
 */
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
}, (error) => {
  return Promise.reject(error);
});

/**
 * INTERCEPTEUR DE RÉPONSE
 * Gère les erreurs globales (ex: Token expiré)
 */
api.interceptors.response.use(
  (res) => res,
  (err) => {
    // Si le serveur répond 401 (Non autorisé), on déconnecte l'utilisateur
    if (err.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      // Éviter les redirections infinies si on est déjà sur la page login
      if (window.location.pathname !== '/login') {
        window.location.href = '/login';
      }
    }
    return Promise.reject(err);
  }
);

export default api;
